package fr.pikeo.logistique;
import android.app.*;import android.content.*;import android.media.AudioAttributes;import android.net.Uri;import android.os.Build;import org.json.*;import java.util.*;
public final class WorkReminders {
 public static void channels(Context c){if(Build.VERSION.SDK_INT<26)return;NotificationManager n=c.getSystemService(NotificationManager.class);for(boolean sound:new boolean[]{false,true}){NotificationChannel ch=new NotificationChannel(sound?"pikeo_work_soft_v1":"pikeo_work_vibrate_v1",sound?"Pauses — bip discret":"Pauses — vibration",NotificationManager.IMPORTANCE_HIGH);ch.enableVibration(true);ch.setVibrationPattern(new long[]{0,350,180,350});ch.setSound(sound?Uri.parse("android.resource://"+c.getPackageName()+"/raw/pikeo_soft_beep"):null,new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_NOTIFICATION).build());n.createNotificationChannel(ch);}NotificationChannel tasks=new NotificationChannel("pikeo_tasks","Tâches et échéances",NotificationManager.IMPORTANCE_HIGH);tasks.enableVibration(true);n.createNotificationChannel(tasks);}
 public static JSONObject config(Context c)throws Exception{return new JSONObject(c.getSharedPreferences("pikeo_work",0).getString("config","{}"));}
 public static void configure(Context c,JSONObject s)throws Exception{c.getSharedPreferences("pikeo_work",0).edit().putString("config",s.toString()).commit();rebuild(c);}
 public static void rebuild(Context c)throws Exception{channels(c);for(String id:new ArrayList<>(c.getSharedPreferences("pikeo_alarms",0).getAll().keySet()))if(id.startsWith("work_"))PikeoAlarmReceiver.cancel(c,id);JSONObject s=config(c);if(!s.optBoolean("enabled",false))return;JSONArray days=s.getJSONArray("days");for(int i=0;i<days.length();i++)for(int event=0;event<6;event++)next(c,"work_"+days.getInt(i)+"_"+event);}
 private static int minutes(String t){String[] a=t.split(":");return Integer.parseInt(a[0])*60+Integer.parseInt(a[1]);}
 public static void next(Context c,String id)throws Exception{JSONObject s=config(c);if(!s.optBoolean("enabled",false))return;String[] a=id.split("_");int day=Integer.parseInt(a[1]),event=Integer.parseInt(a[2]);int b=minutes(s.getString("breakStart")),l=minutes(s.getString("lunchStart"));int[] times={minutes(s.getString("start")),b,b+s.getInt("breakMinutes"),l,l+s.getInt("lunchMinutes"),minutes(s.getString("end"))};String[] titles={"Prise de poste","Début de pause","Fin de pause","Début du déjeuner","Fin du déjeuner","Fin de journée"};int minute=times[event]-8;PikeoAlarmReceiver.schedule(c,id,WorkReminderTime.nextAt(System.currentTimeMillis(),day,minute),"Pikéo — "+titles[event]+" dans 8 min");}
}
